def gen_tts():
    audio_dir = Path("output/2026-08-11/audio")
    audio_dir.mkdir(exist_ok=True)
    
    for day, text in THAI_PREDICTIONS.items():
        # Generate TTS using gTTS
        tts = gTTS(text=text, lang='th', slow=False)
        out_path = audio_dir / f"{day}.mp3"
        tts.save(str(out_path))
        
        size = out_path.stat().st_size
        print(f"✅ {day} ({DAY_TH[day]}) — {size:,} bytes")
    
    print(f"\n🎉 Complete! All {len(THAI_PREDICTIONS)} Thai TTS files generated.")
    print(f"📁 Location: {audio_dir}")

if __name__ == "__main__":
    gen_tts()